@Test
public void testTubePullThread() throws Exception {
    final Configuration config = new Configuration();
    config.setString(Constants.CLUSTER_ID, "ci");
    config.setString(Constants.TUBE_MASTER_ADDRESS, "ma");
    Map<String, Map<String, Long>> topicToOffset = new HashMap<>();
    topicToOffset.put("topic", new HashMap<>());
    MultiTenancyTubeConsumer tubeConsumerWrapper = new MultiTenancyTubeConsumer(config, topicToOffset, 1, Throwable::printStackTrace);
    TestContext context = new TestContext();
    tubeConsumerWrapper.start(context);
    PullMessageConsumer mockPullMessageConsumer = mock(PullMessageConsumer.class);
    TubePullThread tubePullThread = tubeConsumerWrapper.new TubePullThread(mockPullMessageConsumer, "topic", new ArrayList<>(), topicToOffset.get("topic"), 1024);
    ConsumerResult consumerResult1 = constructConsumerResult("topic", 1, 200, "data1");
    ConsumerResult consumerResult2 = constructConsumerResult("topic", 50, 200, "data2");
    ConsumerResult consumerResult3 = constructConsumerResult("topic", 100, 200, "data3");
    when(mockPullMessageConsumer.getMessage()).thenReturn(consumerResult1, consumerResult2, consumerResult3);
    when(mockPullMessageConsumer.confirmConsume("confirmContext", true)).thenReturn(consumerResult1, consumerResult2, consumerResult3);
    tubePullThread.start();
    while (true) {
        if (context.getCount() < 3) {
            //noinspection BusyWait
            Thread.sleep(100);
        } else {
            assertEquals(topicToOffset.size(), 1);
            assertEquals((long) topicToOffset.get("topic").get("111:topic:222"), 100L);
            tubePullThread.cancel();
            tubePullThread.interrupt();
            tubePullThread.join();
            break;
        }
    }
}

